composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      KILLBILL_DAO_URL: "jdbc:mysql://{{serviceName}}-mysql:3306/killbill"
      KILLBILL_DAO_USER: killbill
      KILLBILL_DAO_PASSWORD: {{env.MYSQL_PASSWORD}}
      MYSQL_PASSWORD: {{env.MYSQL_PASSWORD}}
    depends_on:
      - {{serviceName}}-mysql
  {{serviceName}}-mysql:
    image: mysql:8
    container_name: {{serviceName}}-mysql
    restart: unless-stopped
    environment:
      MYSQL_DATABASE: killbill
      MYSQL_USER: killbill
      MYSQL_PASSWORD: {{env.MYSQL_PASSWORD}}
      MYSQL_ROOT_PASSWORD: {{env.MYSQL_PASSWORD}}
    volumes:
      - {{appDataPath}}/mysql:/var/lib/mysql
